// THE MODEL REGISTRY: every kind of object the game draws, and whether what
// the player sees is a MODEL made in Blender (`make models`, committed in
// `pwa/models/`, the `blender-assets` skill) or GENERATED by the game's own
// code at run time. One row an asset: its ids, where each half lives and
// the switch that sends a modelled asset back to its code.
//
// A modelled asset keeps its code builder — the switch's other side, and
// what the model is judged against — so every row names one. The water, the
// shore's ground, the sky, the sea ice, the wake, the spray and the
// footprints are surfaces and effects, not objects, and are not rows.
//
// `tests/model_registry_test.ts` holds it to the tree: the Blender rows'
// files are exactly the files the build packs (`modelFiles`), every path
// named here exists, and `docs/models.md` carries `renderModelRegistry()`
// (`make model-registry` rewrites it, and prettier pads its columns).
// DOM-free and three-free.

import { CRAFT_IDS, FAUNA_IDS } from "@engine";

import { BIRD_IDS } from "./bird-defs.ts";
import { FLORA } from "./flora-defs.ts";
import { TREE_KINDS } from "./tree-variants.ts";

export type ModelSource = "blender" | "code";

export type ModelRow = {
  /** What is drawn, in the player's words. */
  asset: string;
  /** Every id of it the game draws. */
  ids: readonly string[];
  /** Where the drawn geometry comes from today. */
  source: ModelSource;
  /** The code that builds it — the only builder of a `code` row, the
   * switched-off one of a `blender` row. */
  code: readonly string[];
  /** What puts it in the scene. */
  drawnBy: string;
  /** A modelled asset's Blender builder, its committed files (published
   * names under `pwa/models/`, and their shape as one pattern), and the
   * build switch that turns it back. */
  blender?: { builder: string; files: readonly string[]; pattern: string; switch: string };
  /** Anything a reader should know that the columns do not say. */
  note?: string;
};

